import numpy as np
from scipy import stats

MAX_DRIVERS = 5

def design(feats):
    # Identify highly associated features (p < 0.001)
    p_values = [stats.ttest_ind(feats.x[feats.y==1, feats.column(fid)], 
                               feats.x[feats.y==0, feats.column(fid)], 
                               equal_var=False)[1] 
                for fid in feats.ids]

    strong_features = [fid for fid, p in zip(feats.ids, p_values) if p < 0.001]

    # If fewer than 2 strong features, return empty design
    if len(strong_features) < 2:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Check for highly correlated pairs (|r| >= 0.6)
    correlated_pairs = []
    for i, f1 in enumerate(strong_features):
        for j, f2 in enumerate(strong_features[i+1:], i+1):
            corr = np.corrcoef(feats.x[:, feats.column(f1)], 
                              feats.x[:, feats.column(f2)])[0,1]
            if abs(corr) >= 0.6:
                correlated_pairs.append((f1, f2))

    # If we have correlated pairs, use the first pair's features
    if correlated_pairs:
        f1, f2 = correlated_pairs[0]
        # Use both features but only include one in drivers
        return Design(
            drivers=(f1,),
            columns=(f1, f2),
            products=(),
            loadings={f1: 0.5, f2: 0.5}
        )

    # Otherwise, just use the top feature
    return Design(
        drivers=(strong_features[0],) if strong_features else (),
        columns=tuple(strong_features[:2]),
        products=(),
        loadings={strong_features[0]: 1.0} if strong_features else {}
    )

